{"code": "import re,ast
H=[]
for r in load_history():
 if r['family']!='spiral_classification':continue
 cs=[]
 for m in re.finditer(r'### Choice ([A-E])\n(.*?)(?=### Choice |## Your answer|\Z)',r['question'],re.S):
  l,t=m.groups()
  def get(p):
   z=re.search(p,t);return z.group(1) if z else None
  dep=get(r'- Depth: (\d+)'); ln=get(r'- Layer norm per layer: (\[[^\]]*\])');lr=get(r'- Learning rate: ([\deE.+-]+)'); opt=get(r'- Optimizer: (\w+)')
  if not all([dep,ln,lr,opt]):continue
  cs.append(dict(l=l,d=int(dep),ln=ast.literal_eval(ln),res=get(r'- Residual connections: (\w+)')=='True',act=get(r'- Activation: (\w+)'),lr=float(lr),opt=opt))
 H.append((r,cs))
P=[]
for r,cs in H:
 order=re.findall('[A-E]',r['answer'])
 for a in cs:
  if a['res'] or a['d']<3 or sum(a['ln'])!=1 or a['ln'].index(True)<a['d']-2 or a['act'] not in ['silu','gelu']:continue
  for b in cs:
   if sum(b['ln'])>1 and b['lr']==a['lr'] and b['opt']==a['opt'] and a['l'] in order and b['l'] in order:
    P.append((r,a,b,order.index(a['l'])<order.index(b['l'])))
print('history late vs moreLN',len(P),sum(x[3] for x in P),'questions',len(set(x[0]['question_id'] for x in P)))
for opt in ['Adam','AdamW','RMSprop','SGD','Adagrad']:
 q=[x for x in P if x[1]['opt']==opt];print(opt,len(q),sum(x[3] for x in q))
print([(r['question_id'],a['l'],b['l'],win,a['opt'],a['lr']) for r,a,b,win in P])"}

